PALETTE = {'o': (239, 76, 24), 'w': (255, 255, 255)}

def banner(color=True, title=True):
    lines = []
    for index, (row, shades) in enumerate(zip(ART, SHADES)):
        if not color:
            row = ''.join(chr(0x2800 + m) if m else ' ' for m in WHITE_MASKS[index])
        line = '  '
        last = None
        for ch, shade in zip(row, shades):
            if color and shade != last and ch != ' ':
                r, g, b = PALETTE[shade]
                line += f'\033[38;2;{r};{g};{b}m'
                last = shade
            line += ch
        lines.append(line + ('\033[0m' if color else ''))
    if title:
        label = 'P R O M E T H E U S'.center(60)
        lines.extend(['', '  ' + ('\033[1;38;2;239;76;24m' if color else '') + label + ('\033[0m' if color else '')])
    return '\n'.join(lines)

